
const L="data:image/webp;base64,",WM="data:image/webp;base64,";document.querySelectorAll('[data-l]').forEach(i=>i.src=L);document.querySelectorAll('[data-w]').forEach(i=>i.src=WM);document.documentElement.style.setProperty('--m','url('+L+')');
const $=s=>document.querySelector(s),RM=matchMedia('(prefers-reduced-motion:reduce)').matches;

// loader
const ld=$('#ld');document.body.classList.add('ld');
let pr=0,loaded=document.readyState==='complete',fin=false;const t0=performance.now(),MIN=RM?200:1400;
addEventListener('load',()=>loaded=true);setTimeout(()=>loaded=true,9000);
(function tk(now){const t=Math.min(1,(now-t0)/MIN);let g=1-Math.pow(1-t,3);if(!loaded)g=Math.min(g,.9);
 pr+=(g*100-pr)*.14;if(g>=1&&pr>99.4)pr=100;
 ld.style.setProperty('--pr',pr.toFixed(2));$('#pc').textContent=Math.round(pr)+'%';
 if(pr>=100&&!fin){fin=true;setTimeout(()=>{ld.classList.add('out');setTimeout(()=>document.body.classList.add('rd'),500);setTimeout(()=>{document.body.classList.remove('ld');ld.remove()},1800)},350);return}
 requestAnimationFrame(tk)})(t0);
// headline split
const h=$('#h1');h.innerHTML=h.textContent.split(' ').map((w,i)=>`<span class="w" style="--i:${i}">${w}</span>`).join(' ');
// orbit
const dv=[],fill=(id,arr,r,dir,sp,c)=>arr.forEach((t,i)=>{const e=document.createElement('span');e.className='dv '+c;e.textContent=t;$('#orb').appendChild(e);dv.push({e,r,dir,sp,a:i*6.2832/arr.length-1.5708})});
fill('#rn',['Engineering','AI','Cloud','Growth','Products','Launchpad'],28,-1,.105,'n');
fill('#ro',['Studios','Capital','Media','Labs','Ventures'],46,1,.0785,'');
(function oo(now){const t=RM?0:now/1000;dv.forEach(d=>{const a=d.a+d.dir*t*d.sp;d.e.style.left=50+d.r*Math.cos(a)+'%';d.e.style.top=50+d.r*Math.sin(a)+'%'});requestAnimationFrame(oo)})(0);
// scroll: progress, nav, timelines
const on=(box,sel,p)=>{box.style.setProperty('--p',Math.min(1,Math.max(0,p)).toFixed(3));[...box.querySelectorAll(sel)].forEach((n,i,a)=>n.classList.toggle('on',p>=(i/(a.length-1||1))-.02))};
const navLinks=[...document.querySelectorAll('nav ul a')];
function sc(){const y=scrollY,H=document.documentElement.scrollHeight-innerHeight;$('#bar').style.transform=`scaleX(${H?y/H:0})`;$('#hd').classList.toggle('s',y>40);
 const current=[...document.querySelectorAll('main section[id]')].filter(section=>section.getBoundingClientRect().top<=innerHeight*.35).pop()?.id;
 navLinks.forEach(link=>link.classList.toggle('active',link.getAttribute('href')==='#'+current));
 [['#pipe','div'],['#pth','.st']].forEach(([s,c])=>{const b=$(s),r=b.getBoundingClientRect();on(b,c,(innerHeight*.75-r.top)/(r.height+innerHeight*.05))});}
addEventListener('scroll',sc,{passive:true});sc();
// reveal
const io=new IntersectionObserver(e=>e.forEach(x=>{if(x.isIntersecting){x.target.classList.add('in');io.unobserve(x.target)}}),{threshold:.15});
document.querySelectorAll('.rv').forEach(e=>io.observe(e));
// pointer effects
let mx=innerWidth/2,my=innerHeight/2,lx=mx,ly=my;
addEventListener('pointermove',e=>{mx=e.clientX;my=e.clientY;
 const k=$('#k').getBoundingClientRect(),dx=(mx-(k.left+k.width/2))/innerWidth,dy=(my-(k.top+k.height/2))/innerHeight;
 if(!RM)$('#kin').style.transform=`rotateY(${dx*26}deg) rotateX(${-dy*22}deg)`});
document.querySelectorAll('.p').forEach(p=>p.addEventListener('pointermove',e=>{const r=p.getBoundingClientRect();p.style.setProperty('--x',e.clientX-r.left+'px');p.style.setProperty('--y',e.clientY-r.top+'px')}));
document.querySelectorAll('.mag').forEach(b=>{b.addEventListener('pointermove',e=>{const r=b.getBoundingClientRect();b.style.transform=`translate(${(e.clientX-r.left-r.width/2)*.25}px,${(e.clientY-r.top-r.height/2)*.4}px)`});b.addEventListener('pointerleave',()=>b.style.transform='')});
// canvas embers + light
const cv=$('#fx'),c=cv.getContext('2d');let W,D,P=[];
function rs(){D=Math.min(devicePixelRatio||1,2);W=cv.width=innerWidth*D;cv.height=innerHeight*D;P=Array.from({length:Math.round(innerWidth/16)},()=>({x:Math.random()*W,y:Math.random()*cv.height,r:(Math.random()*1.4+.4)*D,v:(Math.random()*.25+.08)*D,a:Math.random()*.6+.2,t:Math.random()<.35}))}
addEventListener('resize',rs);rs();
(function f(){lx+=(mx-lx)*.09;ly+=(my-ly)*.09;$('#light').style.transform=`translate(${lx}px,${ly}px)`;
 c.clearRect(0,0,W,cv.height);
 for(const p of P){if(!RM){p.y-=p.v;p.x+=Math.sin(p.y/90+p.a*9)*.15*D}if(p.y<-5){p.y=cv.height+5;p.x=Math.random()*W}
  const d=Math.hypot(p.x/D-mx,p.y/D-my),g=Math.max(0,1-d/260);
  c.fillStyle=p.t?`rgba(226,164,90,${p.a*.5+g})`:`rgba(217,215,211,${p.a*.28+g*.5})`;
  c.beginPath();c.arc(p.x,p.y,p.r*(1+g*1.6),0,6.283);c.fill();
  if(g>.4)for(const q of P){const e=Math.hypot(p.x-q.x,p.y-q.y);if(e<90*D&&q!==p){c.strokeStyle=`rgba(226,164,90,${(1-e/(90*D))*g*.5})`;c.lineWidth=D*.6;c.beginPath();c.moveTo(p.x,p.y);c.lineTo(q.x,q.y);c.stroke()}}}
 requestAnimationFrame(f)})();


const contactForm=document.querySelector('#contact-form');
const formStatus=document.querySelector('#form-status');
contactForm.addEventListener('submit',e=>{
 e.preventDefault();
 const data=new FormData(contactForm);
 const subject=`New enquiry from ${data.get('name')}`;
 const body=[`Name: ${data.get('name')}`,`Email: ${data.get('email')}`,`Company: ${data.get('company')||'Not provided'}`,`Phone: ${data.get('phone')||'Not provided'}`,'',`${data.get('message')}`].join('\n');
 window.location.href=`mailto:thekolli.in@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
 formStatus.textContent='Your email app should open with the enquiry ready to send.';
});

const menuToggle=document.querySelector('.menu-toggle');
const mobileNav=document.querySelector('#mobile-nav');
menuToggle.addEventListener('click',()=>{
 const open=mobileNav.classList.toggle('open');
 menuToggle.classList.toggle('open',open);
 menuToggle.setAttribute('aria-expanded',String(open));
 menuToggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');
});
mobileNav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{
 mobileNav.classList.remove('open');
 menuToggle.classList.remove('open');
 menuToggle.setAttribute('aria-expanded','false');
 menuToggle.setAttribute('aria-label','Open navigation');
}));
